public class Solution {

    public static class InvalidFieldException extends RuntimeException {

        private final String field;

        public InvalidFieldException(String field, String message) {
            super(message);
            this.field = field;
        }

        public String field() {
            return field;
        }
    }

    public static String register(String name, int age) {
        if (name == null || name.isBlank()) {
            throw new InvalidFieldException("name", "name is blank");
        }
        if (age < 18) {
            throw new InvalidFieldException("age", "age is " + age);
        }
        return name + "/" + age;
    }

    public static String describeFailure(String name, int age) {
        try {
            return register(name, age);
        } catch (InvalidFieldException invalid) {
            return invalid.field() + " -> " + invalid.getMessage();
        }
    }
}

