import java.util.ArrayList;
import java.util.List;

public class Solution {

    static final class Probe implements AutoCloseable {

        private final String name;
        private final List<String> log;
        private final boolean failOnClose;

        Probe(String name, List<String> log, boolean failOnClose) {
            this.name = name;
            this.log = log;
            this.failOnClose = failOnClose;
            log.add("open:" + name);
        }

        @Override
        public void close() {
            log.add("close:" + name);
            if (failOnClose) {
                throw new IllegalStateException("close:" + name);
            }
        }
    }

    public static String audit(boolean failInBody, boolean failOnClose) {
        List<String> log = new ArrayList<>();
        try (Probe first = new Probe("a", log, failOnClose);
             Probe second = new Probe("b", log, failOnClose)) {
            log.add("body");
            if (failInBody) {
                throw new IllegalStateException("body");
            }
        } catch (RuntimeException thrown) {
            log.add("caught:" + thrown.getMessage());
            for (Throwable suppressed : thrown.getSuppressed()) {
                log.add("suppressed:" + suppressed.getMessage());
            }
        }
        return String.join(",", log);
    }
}

