import java.util.Objects;

public class Solution {

    private final int id;

    public Solution(int id) {
        this.id = id;
    }

    public int id() {
        return id;
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || getClass() != other.getClass()) {
            return false;
        }
        return id == ((Solution) other).id;
    }

    @Override
    public int hashCode() {
        return Integer.hashCode(id);
    }

    @Override
    public String toString() {
        return "Solution(" + id + ")";
    }

    public static class Tagged extends Solution {

        private final String tag;

        public Tagged(int id, String tag) {
            super(id);
            this.tag = tag;
        }

        @Override
        public boolean equals(Object other) {
            if (this == other) {
                return true;
            }
            if (other == null || getClass() != other.getClass()) {
                return false;
            }
            Tagged tagged = (Tagged) other;
            return id() == tagged.id() && Objects.equals(tag, tagged.tag);
        }

        @Override
        public int hashCode() {
            return Objects.hash(id(), tag);
        }

        @Override
        public String toString() {
            return "Tagged(" + id() + "," + tag + ")";
        }
    }
}
